---@field QuizCountText                 	TMPro.TextMeshProUGUI
local PVPArenaQuizPlayerGroupNode = Class('PVPArenaQuizPlayerGroupNode')

------------ import ------------
local KTool          = CS.Engine.Lib.KTool
---@type PVPArenaComponent
local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
------------ import ------------

------------ define ------------
local CellRankingName  = "CellRanking"
local CellRankingPath  = "Game.UI.PVPArena.PVPArenaQuizRankingCell"
local CellSelectedName = "CellSelected"
local CellSelectedPath = "Game.UI.PVPArena.PVPArenaQuizSelectedCell"
------------ define ------------

function PVPArenaQuizPlayerGroupNode:__init()
end

function PVPArenaQuizPlayerGroupNode:__delete()
end

--function PVPArenaQuizPlayerGroupNode:Awake()
--end

function PVPArenaQuizPlayerGroupNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

---InitQuizData
---@param mainPanelStatus Constants.PVPArenaMainPanelStatus
---@param quizzed table 已竞猜的玩家列表
---@param pvpArenaDojo  PVPArenaDojo
function PVPArenaQuizPlayerGroupNode:InitQuizData(mainPanelStatus, quizzed, pvpArenaDojo)
    local cellName, cellPath, count
    local listData          = {}
    local matcherInfo       = pvpArenaDojo.matcherInfo
    local playerId2Group    = pvpArenaComponent:GetPlayerId2Group()

    local CreateData = function(info, playerId)
        return {
            info = info,
            quizzedNum = checkNumber(info.quizzedNum),
            playerId = playerId,
            group = playerId2Group[tostring(playerId)].text,
        }
    end

    if mainPanelStatus == Constants.PVPArenaMainPanelStatus.NoQuizComplete or mainPanelStatus == Constants.PVPArenaMainPanelStatus.QuizComplete then
        for i, playerId in ipairs(quizzed) do
            local info = matcherInfo[tostring(playerId)]
            table.insert(listData, CreateData(info, playerId))
        end
        cellName, cellPath = CellSelectedName, CellSelectedPath

    elseif mainPanelStatus == Constants.PVPArenaMainPanelStatus.Notice then
        count = 0
        for playerId, info in pairs(matcherInfo) do
            count = count + 1
            table.insert(listData, CreateData(info, playerId))
        end
        table.sort(listData, function(a, b)
            return a.quizzedNum > b.quizzedNum
        end)

        local oldQuizzedNum = 0
        local rankNum = 1
        for i, data in ipairs(listData) do
            local quizzedNum = data.quizzedNum
            --- 有票就有排名
            if quizzedNum <= 0 then break end
            data.rankNum = rankNum
            if oldQuizzedNum ~= quizzedNum then
                rankNum = rankNum + 1
            end
            oldQuizzedNum = quizzedNum
        end
        cellName, cellPath = CellRankingName, CellRankingPath

    end

    return cellName, cellPath, listData, count
end

