function PVPArenaQuizPlayerGroupNode:RefreshUI()
    ---@type PVPArenaDojo
    local pvpArenaDojo      = pvpArenaComponent:GetPVPArenaDojo()
    local quizzed       = checkTable(pvpArenaDojo.quizzed)
    --- 投过几次票
    local quizNum       = table.count(quizzed)
    --- 竞猜票数量
    local quizTicketNum = checkNumber(pvpArenaDojo.quizTicketNum)
    --- 能投多少次
    local quizMaxNum    = quizNum + quizTicketNum

    ---@type Constants.PVPArenaMainPanelStatus
    local mainPanelStatus   = pvpArenaComponent:GetMainPanelStatus()
    local isEmpty = mainPanelStatus == Constants.PVPArenaMainPanelStatus.NoQuiz
    KTool.SetActive(self.EmptyNode.gameObject, isEmpty)
    KTool.SetActive(self.LoopListView.gameObject, not isEmpty)

    self.QuizTitleText.text = mainPanelStatus == Constants.PVPArenaMainPanelStatus.Notice and localize("推选排名") or localize("已推选玩家")

    local isShowQuizCount = mainPanelStatus ~= Constants.PVPArenaMainPanelStatus.Notice
    KTool.SetActive(self.QuizCountText.gameObject, isShowQuizCount)
    if isShowQuizCount then
        self.QuizCountText.text = string.format("%s/%s", quizNum, quizMaxNum)
    end

    if not isEmpty then
        local cellName, cellPath, listData, count = self:InitQuizData(mainPanelStatus, quizzed, pvpArenaDojo)
        self.cellName = cellName
        self.cellPath = cellPath
        self.listData = listData
        count = count or quizNum
        if not self.LoopListView.IsListViewInit then
            self.LoopListView:InitListView(count, Bind(self, self.OnGetItemByIndex))
        else
            GameUtils.ReloadData(self.LoopListView, count)
        end
    end
end

function PVPArenaQuizPlayerGroupNode:OnGetItemByIndex(listView, idx)
    if idx < 0 then
        return nil
    end

    local index = idx + 1
    local data = self.listData[index]

    local cell = listView:NewListViewItem(self.cellName)
    local node = GetLuaBehaviour(cell.gameObject, self.cellPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        local mbEnv = node.Env
        mbEnv:RefreshUI(data)
    end

    return cell
end

---------------------------------------------------
--- ui logic end --
---------------------------------------------------

return PVPArenaQuizPlayerGroupNode